import type { VendorQuoteAdapterInput } from "../types.js";
import {
  providerDispatchAuthorizationDenial,
  type ProviderDispatchAuthorizationDenial,
} from "./providerDispatchAuthorization.js";

/**
 * Generated by `npm run fixture:onboard -- rmfg --stage=live` (OVD-687).
 *
 * Adapter-side binding for production RMFG launches: the shared
 * provider check (`providerDispatchAuthorization.ts`) bound to the
 * RMFG envelope identity. The identity is NOT reviewed: it is absent
 * from `REVIEWED_PROVIDER_DISPATCH_ENVELOPES` and has no review row, so no
 * permit can name it. Declaring it here admits nothing.
 */
export const RMFG_DISPATCH_ENVELOPE = Object.freeze({ id: "rmfg-quote-envelope", version: 1 });

export type RmfgDispatchAuthorizationDenial = ProviderDispatchAuthorizationDenial;

export function rmfgDispatchAuthorizationDenial(
  input: VendorQuoteAdapterInput,
  nowMs: number = Date.now(),
): RmfgDispatchAuthorizationDenial | null {
  return providerDispatchAuthorizationDenial(
    input,
    { provider: "rmfg", ...RMFG_DISPATCH_ENVELOPE },
    nowMs,
  );
}
